          (loadYaml(read('pubspec.yaml')) as YamlMap)['version'] as String;
      final rootName = (loadYaml(read('pubspec.yaml')) as YamlMap)['name']
          as String;
      final appVersion =
          (loadYaml(read('flutter_app/pubspec.yaml')) as YamlMap)['version']
              as String?;
