      final lockedRoot =
          (lock['packages'] as YamlMap)[rootName] as YamlMap?;
      expect(
        lockedRoot,
        isNotNull,
        reason: 'flutter_app/pubspec.lock must record the $rootName path '
            'dependency.',
      );
